#include <iostream>
#include <string>
using namespace std;

int main() {
    string players;
    cin >> players;

    int consecutive = 1;

    for (size_t i = 1; i < players.size(); ++i) {
        if (players[i] == players[i - 1])
            ++consecutive;
        else
            consecutive = 1;

        if (consecutive >= 7) {
            cout << "YES\n";
            return 0;
        }
    }

    cout << "NO\n";
    return 0;
}

